add("home.alert.winter.body", "Half as many tourists, and red flags are common. Keep spare balloons on the ground.", "Turist yarı yarıya az, kırmızı bayrak sık. Gereksiz balonları yerde tut.", "Nur halb so viele Touristen, und rote Flaggen sind häufig. Lass überzählige Ballone am Boden.", "La mitad de turistas y muchas banderas rojas. Deja en tierra los globos que sobran.", "観光客は半分、赤い旗も多い。余分な気球は地上に置いておこう。", "관광객은 절반, 빨간 깃발도 잦습니다. 남는 열기구는 지상에 두세요.")
add("home.alert.dominance", "You hold %@ of the market.", "Pazarın %@ kadarı senin.", "Dir gehören %@ des Marktes.", "Tienes el %@ del mercado.", "市場の%@を握っている。", "시장의 %@를 차지했습니다.")
add("home.alert.dominance.body", "The Competition Authority is watching you.", "Rekabet Kurumu seni izliyor.", "Die Wettbewerbsbehörde beobachtet dich.", "La autoridad de competencia te vigila.", "競争当局が目を光らせている。", "경쟁 당국이 지켜보고 있습니다.")
add("home.alert.mission", "Today's mission: %1$@ (+%2$@)", "Bugünkü görev: %1$@ (+%2$@)", "Heutiger Auftrag: %1$@ (+%2$@)", "Misión de hoy: %1$@ (+%2$@)", "今日の依頼：%1$@（+%2$@）", "오늘의 임무: %1$@ (+%2$@)")
add("home.alert.missionSelf", "If you fly yourself, today's mission: %1$@ (+%2$@)", "Kendin uçurursan bugünkü görev: %1$@ (+%2$@)", "Wenn du selbst fliegst, heutiger Auftrag: %1$@ (+%2$@)", "Si pilotas tú, misión de hoy: %1$@ (+%2$@)", "自分で飛べば今日の依頼：%1$@（+%2$@）", "직접 조종하면 오늘의 임무: %1$@ (+%2$@)")
add("home.alert.tapSelf", "Tap to take the flight yourself.", "Dokun, uçuşu sen üstlen.", "Tippe, um selbst zu fliegen.", "Toca para pilotar tú.", "タップして自分で飛ぶ。", "탭해서 직접 조종하세요.")
add("home.alert.ban", "You're banned from flying.", "Uçuş yasağın var.", "Du hast Flugverbot.", "Tienes prohibido volar.", "飛行禁止処分中。", "운항 금지 중입니다.")
add("home.alert.ban.body", "Days left on the ban: %@.", "Yasağın bitmesine kalan gün: %@.", "Verbleibende Tage: %@.", "Días de prohibición restantes: %@.", "禁止の残り日数：%@。", "남은 금지 일수: %@.")
